// Package http provides an in-process HTTP git server for testing.
package http

import (
	"errors"
	"fmt"
	"net"
	gohttp "net/http"
	"time"

	"github.com/go-git/go-git/v6/backend"
	"github.com/go-git/go-git/v6/plumbing/transport"
)

const (
	addr = "127.0.0.1:0"
)

type server struct {
	l transport.Loader

	ln  net.Listener
	srv *gohttp.Server
}

// FromLoader creates an HTTP git server backed by the given loader.
func FromLoader(l transport.Loader) (*server, error) { //nolint:revive // unexported-return is intentional
	s := &server{
		l: l,
	}
	return s, nil
}

func (s *server) Start() (string, error) {
	h := backend.New(s.l)

	var err error
	s.ln, err = net.Listen("tcp", addr)
	if err != nil {
		return "", fmt.Errorf("cannot listen to TCP: %w", err)
	}

	s.srv = &gohttp.Server{
		Addr:         addr,
		Handler:      h,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 15 * time.Second,
		IdleTimeout:  60 * time.Second,
	}

	go func() {
		_ = s.srv.Serve(s.ln)
	}()

	return s.Endpoint()
}

func (s *server) Endpoint() (string, error) {
	if s.ln != nil && s.srv != nil {
		return "http://" + s.ln.Addr().String(), nil
	}

	return "", errors.New("failed to get endpoint: server not started")
}

func (s *server) Close() error {
	// s.srv.Close() closes the listener internally; calling s.ln.Close()
	// separately would close it twice and return "use of closed network
	// connection" from the second close.
	return s.srv.Close()
}

// Package server provides test helpers for running in-process git servers.
package server

import (
	"fmt"
	"net/url"
	"testing"

	"github.com/go-git/go-billy/v6"
	fixtures "github.com/go-git/go-git-fixtures/v6"

	"github.com/go-git/go-git/v6/plumbing/transport"
	"github.com/go-git/go-git/v6/storage"
	"github.com/go-git/go-git/v6/storage/filesystem"
)

type fixturesLoader struct {
	dot billy.Filesystem
}

var _ transport.Loader = &fixturesLoader{}

func (f *fixturesLoader) Load(_ *url.URL) (storage.Storer, error) {
	if f.dot == nil {
		return nil, fmt.Errorf("cannot load endpoint: fixture not set")
	}

	// Re-use the pre-extracted filesystem for every request. The server is
	// read-only (upload-pack only), so sharing the underlying billy.Filesystem
	// across storage instances is safe and avoids re-extracting the tgz on
	// every clone or fetch.
	return filesystem.NewStorage(f.dot, nil), nil
}

// Loader returns a transport.Loader backed by fix. The fixture's .git directory
// is extracted exactly once (into memory) when Loader is called; all subsequent
// server requests share the same extracted filesystem.
func Loader(t testing.TB, fix *fixtures.Fixture) transport.Loader {
	t.Helper()
	if fix == nil {
		t.Fatal("Loader: fixture must not be nil")
	}
	dot, err := fix.DotGit(fixtures.WithMemFS())
	if err != nil {
		t.Fatal("Loader: DotGit failed:", err)
	}
	return &fixturesLoader{dot: dot}
}

package server

import (
	"io"

	"github.com/go-git/go-git/v6/internal/server/http"
	"github.com/go-git/go-git/v6/plumbing/transport"
)

// GitServer represents a git transport server that can be started and stopped.
type GitServer interface {
	Start() (string, error)
	io.Closer
}

// All returns all available git server implementations backed by the given loader.
func All(l transport.Loader) []GitServer {
	servers := []GitServer{}
	if srv, err := http.FromLoader(l); err == nil {
		servers = append(servers, srv)
	}

	return servers
}

package backend

import (
	"compress/gzip"
	"fmt"
	"io"
	"net/http"
	"regexp"
	"strings"
	"time"

	"github.com/go-git/go-git/v6/plumbing/storer"
	"github.com/go-git/go-git/v6/plumbing/transport"
	"github.com/go-git/go-git/v6/utils/ioutil"
)

type httpService struct {
	pattern *regexp.Regexp
	method  string
	handler func(b *Backend, w http.ResponseWriter, r *http.Request, repo, file, svc string)
	svc     string
}

var httpServices = []httpService{
	{regexp.MustCompile("(.*?)/HEAD$"), http.MethodGet, (*Backend).handleDumbTextFile, ""},
	{regexp.MustCompile("(.*?)/info/refs$"), http.MethodGet, (*Backend).handleInfoRefs, ""},
	{regexp.MustCompile("(.*?)/objects/info/alternates$"), http.MethodGet, (*Backend).handleDumbTextFile, ""},
	{regexp.MustCompile("(.*?)/objects/info/http-alternates$"), http.MethodGet, (*Backend).handleDumbTextFile, ""},
	{regexp.MustCompile("(.*?)/objects/info/packs$"), http.MethodGet, (*Backend).handleDumbInfoPacks, ""},
	{regexp.MustCompile("(.*?)/objects/[0-9a-f]{2}/[0-9a-f]{38,62}$"), http.MethodGet, (*Backend).handleDumbLooseObject, ""},
	{regexp.MustCompile(`(.*?)/objects/pack/pack-[0-9a-f]{40,64}\.pack$`), http.MethodGet, (*Backend).handleDumbPackFile, ""},
	{regexp.MustCompile(`(.*?)/objects/pack/pack-[0-9a-f]{40,64}\.idx$`), http.MethodGet, (*Backend).handleDumbIdxFile, ""},
	{regexp.MustCompile("(.*?)/git-upload-pack$"), http.MethodPost, (*Backend).handleServiceRPC, transport.UploadPackService},
	{regexp.MustCompile("(.*?)/git-receive-pack$"), http.MethodPost, (*Backend).handleServiceRPC, transport.ReceivePackService},
}

// ServeHTTP implements [http.Handler]. It supports both smart and dumb
// HTTP protocols.
func (b *Backend) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	urlPath := strings.TrimPrefix(r.URL.Path, b.Prefix)
	for _, s := range httpServices {
		if m := s.pattern.FindStringSubmatch(urlPath); m != nil {
			if r.Method != s.method {
				renderStatusError(w, http.StatusMethodNotAllowed)
				return
			}

			repo := strings.TrimPrefix(m[1], "/")
			file := strings.Replace(urlPath, repo+"/", "", 1)
			s.handler(b, w, r, repo, file, s.svc)
			return
		}
	}

	renderStatusError(w, http.StatusNotFound)
}

func (b *Backend) handleServiceRPC(w http.ResponseWriter, r *http.Request, repo, _, svc string) {
	version := r.Header.Get("Git-Protocol")
	contentType := strings.ToLower(strings.TrimSpace(r.Header.Get("Content-Type")))

	expectedContentType := strings.ToLower(fmt.Sprintf("application/x-git-%s-request", transport.ServiceName(svc)))
	if contentType != expectedContentType {
		renderStatusError(w, http.StatusForbidden)
		return
	}

	w.Header().Set("Content-Type", fmt.Sprintf("application/x-git-%s-result", transport.ServiceName(svc)))
	w.Header().Set("Connection", "Keep-Alive")
	w.Header().Set("Transfer-Encoding", "chunked")
	w.Header().Set("X-Content-Type-Options", "nosniff")

	var reader io.ReadCloser
	var err error
	switch r.Header.Get("Content-Encoding") {
	case "gzip":
		reader, err = gzip.NewReader(r.Body)
		if err != nil {
			b.logf("error creating gzip reader: %v", err)
			renderStatusError(w, http.StatusInternalServerError)
			return
		}
		defer func() { _ = reader.Close() }()
	default:
		reader = r.Body
	}

	ep, err := transport.ParseURL(repo)
	if err != nil {
		b.logf("error parsing URL: %v", err)
		renderStatusError(w, http.StatusBadRequest)
		return
	}

	if !b.requireReceivePackAuth(w, r, svc) {
		return
	}

	frw := &flushResponseWriter{ResponseWriter: w, log: b.ErrorLog, chunkSize: defaultChunkSize}
	if err := b.Serve(r.Context(), reader, frw, &Request{
		URL:          ep,
		Service:      svc,
		GitProtocol:  version,
		StatelessRPC: true,
	}); err != nil {
		b.logf("error processing request: %v", err)
		renderStatusError(w, http.StatusInternalServerError)
		return
	}
}

func (b *Backend) handleInfoRefs(w http.ResponseWriter, r *http.Request, repo, file, _ string) {
	service := r.URL.Query().Get("service")
	if service == "" {
		hdrNocache(w)
		b.handleDumbSendFile(w, r, repo, file, "text/plain; charset=utf-8")
		return
	}

	if service != transport.UploadPackService && service != transport.ReceivePackService {
		b.logf("unsupported service requested: %q", service)
		renderStatusError(w, http.StatusNotFound)
		return
	}

	if !b.requireReceivePackAuth(w, r, service) {
		return
	}

	ep, err := transport.ParseURL(repo)
	if err != nil {
		b.logf("error parsing URL: %v", err)
		renderStatusError(w, http.StatusBadRequest)
		return
	}

	version := r.Header.Get("Git-Protocol")

	hdrNocache(w)
	w.Header().Set("Content-Type", fmt.Sprintf("application/x-git-%s-advertisement", transport.ServiceName(service)))

	if err := b.Serve(r.Context(), nil, ioutil.WriteNopCloser(w), &Request{
		URL:           ep,
		Service:       service,
		GitProtocol:   version,
		AdvertiseRefs: true,
		StatelessRPC:  true,
	}); err != nil {
		b.logf("error processing request: %v", err)
		renderStatusError(w, http.StatusInternalServerError)
		return
	}
}

// Dumb HTTP handlers — serve static files from the repository filesystem.

func (b *Backend) handleDumbTextFile(w http.ResponseWriter, r *http.Request, repo, file, _ string) {
	hdrNocache(w)
	b.handleDumbSendFile(w, r, repo, file, "text/plain; charset=utf-8")
}

func (b *Backend) handleDumbInfoPacks(w http.ResponseWriter, r *http.Request, repo, file, _ string) {
	hdrCacheForever(w)
	b.handleDumbSendFile(w, r, repo, file, "text/plain; charset=utf-8")
}

func (b *Backend) handleDumbLooseObject(w http.ResponseWriter, r *http.Request, repo, file, _ string) {
	hdrCacheForever(w)
	b.handleDumbSendFile(w, r, repo, file, "application/x-git-loose-object")
}

func (b *Backend) handleDumbPackFile(w http.ResponseWriter, r *http.Request, repo, file, _ string) {
	hdrCacheForever(w)
	b.handleDumbSendFile(w, r, repo, file, "application/x-git-packed-objects")
}

func (b *Backend) handleDumbIdxFile(w http.ResponseWriter, r *http.Request, repo, file, _ string) {
	hdrCacheForever(w)
	b.handleDumbSendFile(w, r, repo, file, "application/x-git-packed-objects-toc")
}

func (b *Backend) handleDumbSendFile(w http.ResponseWriter, _ *http.Request, repo, file, contentType string) {
	loader := b.Loader
	if loader == nil {
		loader = transport.DefaultLoader
	}

	ep, err := transport.ParseURL(repo)
	if err != nil {
		b.logf("error parsing URL: %v", err)
		renderStatusError(w, http.StatusBadRequest)
		return
	}

	st, err := loader.Load(ep)
	if err != nil {
		b.logf("error loading repository: %v", err)
		renderStatusError(w, http.StatusNotFound)
		return
	}

	fss, ok := st.(storer.FilesystemStorer)
	if !ok {
		renderStatusError(w, http.StatusNotFound)
		return
	}

	fs := fss.Filesystem()
	f, err := fs.Open(file)
	if err != nil {
		renderStatusError(w, http.StatusNotFound)
		return
	}
	defer func() { _ = f.Close() }()

	stat, err := fs.Lstat(file)
	if err != nil || !stat.Mode().IsRegular() {
		renderStatusError(w, http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", contentType)
	w.Header().Set("Content-Length", fmt.Sprintf("%d", stat.Size()))
	w.Header().Set("Last-Modified", stat.ModTime().Format(http.TimeFormat))

	frw := &flushResponseWriter{ResponseWriter: w, log: b.ErrorLog, chunkSize: defaultChunkSize}
	if _, err := ioutil.CopyBufferPool(frw, f); err != nil {
		b.logf("error writing response: %v", err)
		renderStatusError(w, http.StatusInternalServerError)
		return
	}
}

func (b *Backend) requireReceivePackAuth(w http.ResponseWriter, r *http.Request, service string) bool {
	// For receive-pack, require authentication as a basic sanity check.
	if service == transport.ReceivePackService && strings.TrimSpace(r.Header.Get("Authorization")) == "" {
		b.logf("missing Authorization header for receive-pack service")
		renderStatusError(w, http.StatusUnauthorized)
		return false
	}
	return true
}

func renderStatusError(w http.ResponseWriter, code int) {
	http.Error(w, fmt.Sprintf("%d %s", code, http.StatusText(code)), code)
}

func hdrNocache(w http.ResponseWriter) {
	w.Header().Set("Expires", "Fri, 01 Jan 1980 00:00:00 GMT")
	w.Header().Set("Pragma", "no-cache")
	w.Header().Set("Cache-Control", "no-cache, max-age=0, must-revalidate")
}

func hdrCacheForever(w http.ResponseWriter) {
	now := time.Now()
	expires := now.Add(365 * 24 * time.Hour)
	w.Header().Set("Date", now.Format(http.TimeFormat))
	w.Header().Set("Expires", expires.Format(http.TimeFormat))
	w.Header().Set("Cache-Control", "public, max-age=31536000")
}

// Package backend provides a unified Git server backend that handles
// git-upload-pack and git-receive-pack over any transport (TCP, HTTP, SSH).
//
// Use [Backend.Serve] or [Backend.ServeConn] for stream-based transports
// (TCP, SSH, pipes). Use [Backend.ServeHTTP] for HTTP (both smart and dumb
// protocols).
package backend

import (
	"context"
	"fmt"
	"io"
	"log"
	"net/url"

	"github.com/go-git/go-git/v6/plumbing/protocol/packp"
	"github.com/go-git/go-git/v6/plumbing/transport"
)

// Request describes a Git server-side operation.
type Request struct {
	// URL identifies the target repository. Loader.Load receives this
	// directly, so callers must ensure the scheme and path are set
	// appropriately for the configured Loader.
	URL *url.URL

	// Service is the Git command: "git-upload-pack" or "git-receive-pack".
	Service string

	// GitProtocol is the value of the GIT_PROTOCOL environment variable
	// (e.g. "version=2"). Empty means protocol v0.
	GitProtocol string

	// AdvertiseRefs, when true, causes the server to advertise references
	// without performing the full pack exchange. Used by HTTP smart
	// protocol for the info/refs endpoint.
	AdvertiseRefs bool

	// StatelessRPC, when true, indicates that the server should operate
	// in stateless request-response mode. Used by HTTP smart protocol.
	StatelessRPC bool
}

// Backend is a Git server that dispatches upload-pack and receive-pack
// requests. It implements [http.Handler] for HTTP and provides [Serve]
// and [ServeConn] for stream-based transports.
type Backend struct {
	// Loader resolves repository URLs to storage. If nil,
	// [transport.DefaultLoader] is used.
	Loader transport.Loader

	// ErrorLog is used to log errors. If nil, errors are not logged.
	ErrorLog *log.Logger

	// Prefix is an HTTP path prefix stripped before route matching.
	// Only used by [ServeHTTP].
	Prefix string
}

// New creates a Backend with the given loader.
func New(loader transport.Loader) *Backend {
	if loader == nil {
		loader = transport.DefaultLoader
	}
	return &Backend{
		Loader: loader,
	}
}

// Serve handles a Git pack protocol request. It resolves the repository
// from req.URL, validates the service, and runs the appropriate server
// command (upload-pack or receive-pack).
//
// The caller is responsible for closing r and w. Errors are returned, not
// written to the wire — the caller decides the error format (pkt-line for
// TCP/SSH, HTTP status for HTTP).
func (b *Backend) Serve(ctx context.Context, r io.ReadCloser, w io.WriteCloser, req *Request) error {
	if req.URL == nil {
		return fmt.Errorf("nil request URL")
	}

	loader := b.Loader
	if loader == nil {
		loader = transport.DefaultLoader
	}

	st, err := loader.Load(req.URL)
	if err != nil {
		return err
	}

	switch req.Service {
	case transport.UploadPackService:
		return transport.UploadPack(ctx, st, r, w, &transport.UploadPackRequest{
			GitProtocol:   req.GitProtocol,
			AdvertiseRefs: req.AdvertiseRefs,
			StatelessRPC:  req.StatelessRPC,
		})
	case transport.ReceivePackService:
		return transport.ReceivePack(ctx, st, r, w, &transport.ReceivePackRequest{
			GitProtocol:   req.GitProtocol,
			AdvertiseRefs: req.AdvertiseRefs,
			StatelessRPC:  req.StatelessRPC,
		})
	default:
		return fmt.Errorf("%w: %s", transport.ErrUnsupportedService, req.Service)
	}
}

func (b *Backend) logf(format string, v ...any) {
	if b.ErrorLog != nil {
		b.ErrorLog.Printf(format, v...)
	}
}

// RequestFromProto converts a Git protocol v0/v1 request (as received
// over TCP by git-daemon) into a [Request].
func RequestFromProto(proto *packp.GitProtoRequest) *Request {
	host := proto.Host
	if host == "" {
		host = "localhost"
	}

	u := &url.URL{
		Scheme: "git",
		Host:   host,
		Path:   proto.Pathname,
	}

	var gitProtocol string
	for _, p := range proto.ExtraParams {
		if gitProtocol == "" {
			gitProtocol = p
		} else {
			gitProtocol += ":" + p
		}
	}

	return &Request{
		URL:         u,
		Service:     proto.RequestCommand,
		GitProtocol: gitProtocol,
	}
}

